ança</th><th>Entregas</th><th>Situação</th><th>Diagnóstico</th></tr></thead><tbody><?php if($webhookEvents===[]):?><tr><td colspan="6">Nenhum evento recebido ainda.</td></tr><?php endif;?><?php foreach($webhookEvents as$event):?><tr><td><?= $escape(date('d/m/Y H:i:s',strtotime((string)($event['last_received_at']?:$event['received_at'])))) ?></td><td><?= $escape($event['event_type']) ?></td><td><?= $escape($event['resource_id']?:'—') ?></td><td><?= (int)$event['delivery_count'] ?></td><td><span class="connection-badge <?= $event['processing_status']==='failed'?'connection-rejected':'connection-approved' ?>"><?= $escape($event['processing_status']==='failed'?'Falhou':($event['processing_status']==='processed'?'Processado':'Recebido')) ?></span></td><td><?= $escape($event['error_message']?:'—') ?></td></tr><?php endforeach;?></tbody></table></div></div></section><?php endif;?>
